const std = @import("std");

fn parsePort(text: []const u8) !u16 {
    const value = std.fmt.parseInt(u32, text, 10) catch return error.InvalidNumber;
    if (value == 0 or value > 65535) return error.OutOfRange;
    return @intCast(value);
}

test "parses a valid port" {
    try std.testing.expectEqual(@as(u16, 8080), try parsePort("8080"));
}

test "rejects zero" {
    try std.testing.expectError(error.OutOfRange, parsePort("0"));
}
